def stream_rows(resource, transform):
    failed = False
    try:
        try:
            while True:
                row = resource.read_next()
                if row is None:
                    break
                yield transform(row)
        except GeneratorExit:
            raise
        except BaseException:
            # An iteration or a transformation error: remember it so a
            # failing cleanup cannot mask the original error.
            failed = True
            raise
    finally:
        try:
            resource.close()
        except BaseException:
            if failed:
                # Preserve the original iteration/transform error.
                pass
            raise
EOF
